                        int newJ = j + k;
                        dp[newI][newJ].first = (dp[newI][newJ].first + current.first) % modulus;
                        dp[newI][newJ].second = (dp[newI][newJ].second + current.second) % modulus;
                    }
                }
            }
            answer = dp[total_n + 1][total_m].second;
        }

